"""Inspect the workspace: list files and, if a SQLite DB exists, show its schema."""
import os
import sqlite3

print("CURRENT DIR:", os.getcwd())
for name in sorted(os.listdir(".")):
    full = os.path.join(".", name)
    kind = "dir" if os.path.isdir(full) else "file"
    size = "" if os.path.isdir(full) else f" ({os.path.getsize(full)} bytes)"
    print(f"- {name} [{kind}]{size}")

print("\nSQLite databases found:")
for name in sorted(os.listdir(".")):
    full = os.path.join(".", name)
    if os.path.isfile(full) and os.path.splitext(name)[1].lower() in (".db", ".sqlite", ".sqlite3", ".sql3"):
        print(f"\n== {name} ==")
        try:
            with sqlite3.connect(full) as conn:
                conn.row_factory = sqlite3.Row
                tables = [
                    row[0]
                    for row in conn.execute(
                        "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"
                    )
                ]
                if not tables:
                    print("  (no user tables)")
                for table in tables:
                    cols = [row[1] for row in conn.execute(f"PRAGMA table_info({table})")]
                    count = conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
                    print(f"  table: {table}, columns: {cols}, rows: {count}")
        except sqlite3.Error as exc:
            print(f"  could not open: {exc}")

